import {canTravel} from './travel.js';
import {facultyCapacity,allocateCredits} from './workload.js';
import {weeklyScene} from './weekly-scene.js';
import {grantCounts,canApplyGrant} from './funding.js';
import {analyticsStatus,analyticsConsent,setAnalyticsConsent,recordAnalytics,exportAnalytics} from './analytics.js';
import {studentAppearance,renderPortrait} from './appearance.js';
import {endingStatistics,renderStatistics,validStatistics} from './statistics.js';
import {createState,stage,proposeSchedule,simulateMonth,decide,validateSave,canContinue,canDefend,ACTIVITIES,PROJECT_PHASES,PROJECT_TITLES,EVENTS,MONTHS,VERSION,abilityScore,WORK_POLICIES,STUDY_POLICIES,DEFAULT_POLICIES,projectThresholds,projectWork,migrateSave,monthlyBudgetCost,salaryBase as engineSalaryBase} from './engine.js';
import {GRANT_TITLES} from './grants.js';
import {ENDINGS,getEndingPages} from './stories.js';
import {DISCIPLINES,getDiscipline,degreeTargets} from './disciplines.js';
import {buildEndingCV,renderCV,validateCVModel} from './cv.js';
import {studentLine} from './dialogue.js';
import {generateKoreanName} from './names.js';
function freshState(seed=Date.now()){const next=createState('',seed,{locale:'ko'});next.creationSeed=seed>>>0;next.name=generateKoreanName(seed,next.gender);return next;}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(ko,en)=>lang==='ko'?ko:en;
const validLetter=x=>x&&Object.hasOwn(ENDINGS,x.ending)&&typeof x.id==='string'&&x.id.length<=100&&typeof x.name==='string'&&x.name.length<=24&&typeof x.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&Number.isInteger(x.month)&&x.month>=0&&x.month<=96&&['close','reserved','distant'].includes(x.relationship)&&(!x.cv||validateCVModel(x.cv))&&(!x.statistics||validStatistics(x.statistics))&&(!x.memories||Array.isArray(x.memories)&&x.memories.length<=16&&x.memories.every(h=>h&&h.kind==='event'&&EVENTS.some(e=>e.id===h.id)&&[0,1].includes(h.choice)&&Number.isInteger(h.month)&&h.month>=0&&h.month<=x.month));
let lang='ko',s=freshState(),gallery=[],letter=null,page=0,busy=false,storageOK=true,installPrompt=null,travelConsent=false,fast=false;
try{lang='ko';s=freshState();const raw=localStorage.getItem('pm-save-v4')||localStorage.getItem('pm-save-v3');if(raw){const parsed=migrateSave(JSON.parse(raw));if(validateSave(parsed)){s=parsed;s.locale='ko';}}const g=JSON.parse(localStorage.getItem('pm-letters-v3')||'[]');if(Array.isArray(g))gallery=g.filter(validLetter).slice(0,40);fast=localStorage.getItem('pm-fast')==='true';}catch{storageOK=false;}
let grantApplication={role:'pi',years:3};
let bridge=null,sequence=0;const requests=new Map();
try{bridge=new Worker('./simulation-worker.js',{type:'module'});bridge.onmessage=e=>{const r=requests.get(e.data.id);if(!r)return;requests.delete(e.data.id);clearTimeout(r.timer);if(e.data.error){r.reject(new Error(e.data.error));return;}if(r.type.startsWith('cv')){const result=e.data.result;if(result&&validateCVModel(result.model)&&typeof result.html==='string')r.resolve(result);else r.reject(new Error('Invalid CV response'));return;}validateSave(e.data.state)?r.resolve(e.data.state):r.reject(new Error('Invalid simulation response'));};bridge.onerror=()=>{for(const r of requests.values()){clearTimeout(r.timer);r.reject(new Error('Simulation worker unavailable'));}requests.clear();bridge.terminate();bridge=null;};}catch{}
function runEngine(type,payload){if(!bridge)return Promise.resolve(type==='cv'?buildEndingCV(payload.state):type==='cv-render'?{model:payload.model,html:renderCV(payload.model)}:type==='month'?simulateMonth(payload.state,payload.plan,payload.options):decide(payload.state,payload.choice));return new Promise((resolve,reject)=>{const id=++sequence;const timer=setTimeout(()=>{requests.delete(id);reject(new Error('Simulation timed out. Please try again.'));bridge?.terminate();bridge=null;},10000);requests.set(id,{resolve,reject,timer,type});bridge.postMessage({id,type,...payload});});}
const name=()=>s.name==='김하늘'&&lang==='en'?'Haneul Kim':s.name;
const endingType=id=>t(id==='gameover'?'지도 종료 기록':'후일담',ENDINGS[id].type);
const genderName=g=>({male:t('남성','Male'),female:t('여성','Female'),unspecified:t('미지정','Unspecified')}[g]);
const facultyLabel=k=>({research:t('학술활동','Scholarship'),teaching:t('교육','Teaching'),admin:t('학교행정','Administration'),mentoring:t('학생관리','Advising')}[k]);
const activityName=id=>id==='conference'&&s.month<24?'현장에서 배운다':id==='experiment'&&s.professorProfile?.labMode==='dry'?t('계산·모델링','Computation & modeling'):ACTIVITIES[id]?.[lang]?.[0]||id;
const activityDescription=id=>id==='conference'&&s.month<24?'발표를 듣고 연구 현장의 질문과 분위기를 배웁니다.':id==='experiment'&&s.professorProfile?.labMode==='dry'?t('모형과 계산으로 가설을 검증한다.','Test a hypothesis with models and computation.'):ACTIVITIES[id]?.[lang]?.[1]||'';
const calendarMonth=m=>((Math.min(m,95)+(lang==='ko'?2:8))%12)+1;
const year=m=>Math.floor(Math.min(m,95)/12)+1;
const monthName=m=>lang==='ko'?`${calendarMonth(m)}월`:new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2000,calendarMonth(m)-1,1)));
const calendar=m=>t(`${year(m)}년차 ${monthName(m)}`,`Year ${year(m)} · ${monthName(m)}`);
function semester(m){const n=calendarMonth(m);return n>=3&&n<=6?t('봄학기','Spring semester'):n>=7&&n<=8?t('여름방학','Summer break'):n>=9&&n<=12?t('가을학기','Fall semester'):t('겨울방학','Winter break');}
const isFestival=()=>[4,10].includes(calendarMonth(s.month));
const isBreak=()=>[1,2,7,8].includes(calendarMonth(s.month));
const visibleStage=()=>s.pending?.kind==='route'?'undergrad':s.pending?.kind==='masters'||s.pendingQueue.some(p=>p.kind==='masters')?'masters':stage(s);
const phase=()=>s.ending?t('지도 종료','Advising complete'):({undergrad:t('학부연구생','Undergraduate researcher'),masters:t('석사과정','Master’s student'),phd:s.route==='integrated'?t('석박사통합과정','Integrated MS / PhD'):t('박사과정','PhD student')}[visibleStage()]);
const currency=n=>lang==='ko'?`${Math.round(n*10).toLocaleString('ko-KR')}만원`:`$${Math.round(n*100).toLocaleString('en-US')}`;
const salaryBase=()=>engineSalaryBase(s);
const affordable=()=>{const stipend=salaryBase()*s.lab.budget.salary/100;return estimate()-stipend<=s.lab.funds&&estimate()<=s.lab.funds+(s.lab.pool??0);};
const estimate=()=>monthlyBudgetCost(s)+({abroad_student:18,abroad_together:34,abroad_shared:26}[s.facultyAction]||0);
const view=()=>['home','lab','journal','letters'].includes(location.hash.slice(1))?location.hash.slice(1):location.hash==='#design'?'lab':'home';
function save(){try{if(validateSave(s))localStorage.setItem('pm-save-v4',JSON.stringify(s));localStorage.setItem('pm-language',lang);localStorage.setItem('pm-letters-v3',JSON.stringify(gallery));localStorage.setItem('pm-fast',String(fast));storageOK=true;}catch{storageOK=false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function archive(){
  if(!s.ending)return;const snapshot=structuredClone(s),id=(snapshot.creationSeed??snapshot.seed)+'-'+snapshot.month+'-'+snapshot.ending;
  let entry=gallery.find(x=>x.id===id);
  if(!entry){entry={id,ending:snapshot.ending,name:snapshot.name,date:new Date().toISOString().slice(0,10),month:snapshot.month,relationship:abilityScore(snapshot,'rapport')>=70?'close':abilityScore(snapshot,'rapport')>=40?'reserved':'distant',career:{...snapshot.career},endingReason:snapshot.endingReason,statistics:endingStatistics(snapshot),memories:snapshot.history.filter(h=>h.kind==='event'&&EVENTS.some(e=>e.id===h.id)&&[0,1].includes(h.choice)).slice(-16).map(h=>({kind:'event',id:h.id,choice:h.choice,month:h.month}))};gallery.unshift(entry);gallery=gallery.slice(0,40);}
  entry.statistics??=endingStatistics(snapshot);entry.memories??=snapshot.history.filter(h=>h.kind==='event'&&EVENTS.some(e=>e.id===h.id)&&[0,1].includes(h.choice)).slice(-16).map(h=>({kind:'event',id:h.id,choice:h.choice,month:h.month}));
  if(snapshot.ending!=='gameover'&&!entry.cv){try{const result=await runEngine('cv',{state:snapshot});if(result)entry.cv=result.model;}catch(error){console.error('CV creation failed',error);}}
  save();return entry;
}
if(s.started&&!s.pending&&!s.ending)s.allocation=allocateCredits(s.allocation,facultyCapacity(s).credits);
archive();

function portrait(){return renderPortrait(studentAppearance(s.creationSeed??s.seed,s.gender));}
function facultyBar(k){const n=s.professor[k];return `<div class="stat ${n<20?'danger':''}"><div><span>${facultyLabel(k)}</span><strong>${Math.round(n)}<small> / 100</small></strong></div><div class="track" role="meter" aria-label="${facultyLabel(k)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(n)}"><span style="width:${n}%"></span></div></div>`;}
function degreeRequirements(){const st=visibleStage(),c=s.career,remaining=Math.max(0,Math.ceil(((st==='undergrad'?24:st==='masters'?s.mastersReviewAt:96)-s.month)/6));const targets=degreeTargets(s.professorProfile?.fieldId,st);let checks=st==='undergrad'?[[t('연구실 경험','Research experience'),t('진학 면담에서 결정','Decide at the admission meeting'),false]]:st==='masters'?[[t('논문 제출','Manuscripts submitted'),`${c.submissions} / ${targets.submissions}`,c.submissions>=targets.submissions],[t('학술 발표','Conference presentations'),`${c.conferences} / ${targets.conferences}`,c.conferences>=targets.conferences]]:[[t('논문 제출','Manuscripts submitted'),`${c.submissions} / ${targets.submissions}`,c.submissions>=targets.submissions],[t('논문 게재','Published papers'),`${c.papers} / ${targets.papers}`,c.papers>=targets.papers],[t('학술 발표','Conference presentations'),`${c.conferences} / ${targets.conferences}`,c.conferences>=targets.conferences],[t('자격시험','Qualifying exam'),c.qual==='passed'?t('통과','Passed'):c.qual==='failed'?t('재응시 준비','Preparing a retake'):t('응시 예정','Upcoming'),c.qual==='passed']];return `<div class="degree-checks"><div class="degree-heading">${t('학위 진행 현황','Degree audit')}<span>${remaining}${t('학기 남음',' semesters left')}</span></div>${checks.map(([label,value,done])=>`<div><span>${label}</span><strong class="${done?'check-done':''}">${done?'✓ ':''}${value}</strong></div>`).join('')}</div>`;}
function sidebar(){return `<aside class="student-panel monthly-panel"><div class="panel-title">${t('지도학생','Your advisee')}<span class="record-id">PM–001</span></div><div class="student-id">${portrait()}<div><h2>${esc(name())}</h2><p>${phase()}</p><span>${genderName(s.gender)} · ${esc(getDiscipline(s.professorProfile?.fieldId).label)}</span></div></div><details class="student-details" ${innerWidth>=900?'open':''}><summary>학위·교수 업무·연구비 상세<span>${['research','teaching','admin','mentoring'].map(k=>`${facultyLabel(k)} ${Math.round(s.professor[k])}`).join(' · ')}</span></summary>${degreeRequirements()}<div class="faculty-overview"><h3>${t('교수 업무 균형','Faculty workload balance')}</h3><div class="core-stats">${['research','teaching','admin','mentoring'].map(facultyBar).join('')}</div><p class="small-note">${t('어느 한 업무가 0이면 지도와 운영을 계속할 수 없습니다.','If any area reaches zero, advising and lab operations must stop.')}</p></div><dl class="student-numbers"><div><dt>${t('연구비 잔액','Research funds')}</dt><dd>${currency(s.lab.funds)}</dd></div><div><dt>${t('인건비 계상률','Stipend allocation')}</dt><dd>${s.lab.budget.salary}%</dd></div><div><dt>h-index · 학술 인용</dt><dd>${s.impact?.hIndex??0} · ${(s.impact?.citations??[]).reduce((a,b)=>a+b,0)}회</dd></div><div><dt>학생인건비 풀링 잔액</dt><dd>${currency(s.lab.pool??0)}</dd></div><div><dt>${t('수상 / 추천서','Awards / recommendations')}</dt><dd>${s.career.awards} / ${s.career.recommendations}</dd></div></dl></details>${s.sabbatical.active?`<p class="state-note">${t('연구년 중','On sabbatical')} · ${s.sabbatical.mode==='away'?t('해외·원격 지도','Abroad / remote advising'):t('국내 지도 유지','Advising from home')}</p>`:''}${lang==='ko'&&s.gender==='male'&&s.service.status!=='none'?`<p class="state-note">전문연 ${s.service.status==='planning'?'선발 준비 상담 중':s.service.status==='consulted'?'후속 복무 계획 상담 완료':'신청 계획 없음'}</p>`:''}</aside>`;}
function progress(){return `<div class="year-progress" aria-label="${t('8년의 지도기간','Eight-year timeline')}">${Array.from({length:8},(_,i)=>`<div class="year ${s.month>=i*12+12?'done':s.month>=i*12?'current':''}"><span>${i+1}${t('년','')}</span><i></i></div>`).join('')}</div><div class="progress-label"><span>${t('학부 1–2년 → 석사 3–4년 → 박사 5–8년','Undergraduate 1–2 → master’s 3–4 → PhD 5–8')}</span><span>${t('또는 석박사통합 3–8년','Or integrated MS/PhD 3–8')}</span></div>`;}
function project(){const p=s.project,ph={...PROJECT_PHASES[p.phase],target:projectThresholds(s).phaseTargets[p.phase]};return `<section class="project-overview"><div class="section-top"><h2>${t('진행 중인 연구','Active research project')}</h2><span>${t('프로젝트','Project')} ${String(p.id).padStart(2,'0')} · ${s.career.completedProjects}${t('개 완료',' completed')}</span></div><h3>${PROJECT_TITLES[p.titleIndex][lang]}</h3><ol class="project-phases">${PROJECT_PHASES.map((x,i)=>`<li class="${i<p.phase?'done':i===p.phase?'current':''}"><span>${i<p.phase?'✓':i+1}</span>${x[lang]}</li>`).join('')}</ol><div class="project-current"><span>${ph[lang]}</span><span>${Math.min(100,Math.round(p.progress/ph.target*100))}% · ${p.conference?t('발표 완료','Presented'):t('발표 준비 중','Presentation pending')}</span></div><div class="project-track"><span style="width:${Math.min(100,p.progress/ph.target*100)}%"></span></div><p class="small-note">${p.phase===5?t('투고 후 심사 중입니다. 논문 쓰기로 수정 의견에 답할 수 있습니다.','Submitted and under review. Writing activities work on revisions.'):t('연구 주간의 수행 결과가 쌓이면 투고·발표를 준비할 수 있습니다. 완료 후 다음 질문으로 넘어갑니다.','Finish one project before beginning the next. Presentations and accepted papers are tracked separately.')}</p><p class="small-note">이번 연구 준비 ${Math.round(projectWork(s))} · 발표 기준 ${projectThresholds(s).conference} · 투고 기준 ${Math.round(projectThresholds(s).submission)}</p></section>`;}
function grantPanel(){const g=s.grants,n=grantCounts(s),active=(g.portfolio??[]).filter(x=>x.id===0||x.end>s.month);return `<details class="grant-panel"><summary><strong>연구과제·학생인건비 관리</strong><span>책임 ${n.pi} / 3 · 전체 ${n.total} / 5</span></summary><div class="grant-content"><ul class="grant-list">${active.map(x=>`<li><strong>${GRANT_TITLES[x.titleIndex]}</strong><span>${x.role==='pi'?'책임연구':'공동참여'} · ${Math.round((x.end-x.start)/12)}년 · ${Math.max(0,x.end-s.month)}개월 남음</span></li>`).join('')}</ul><dl><div><dt>운영비 잔액</dt><dd>${currency(s.lab.funds)}</dd></div><div><dt>학생인건비 통합관리 잔액</dt><dd>${currency(s.lab.pool??0)}</dd></div><div><dt>현재 지급액 / 월</dt><dd>${currency(salaryBase()*s.lab.budget.salary/100)}</dd></div></dl><div class="grant-application"><label>신청 역할<select id="grant-role"><option value="pi" ${grantApplication.role==='pi'?'selected':''}>책임연구자</option><option value="co" ${grantApplication.role==='co'?'selected':''}>공동참여 연구자</option></select></label><label>과제 기간<select id="grant-years">${[1,2,3].map(y=>`<option value="${y}" ${grantApplication.years===y?'selected':''}>${y}년</option>`).join('')}</select></label></div><p>‘연구비 신청’으로 제안서를 제출합니다. 선정 결과는 다음 달에 알려집니다. 책임 3개·전체 5개를 채우면 추가 신청을 할 수 없습니다.</p><p>인건비는 통합관리계정에서 먼저 지급됩니다. 부족하면 운영비에서 충당하며, 적립한 인건비는 과제 종료 뒤에도 학생 지원에 남습니다. 겨울에는 연차보고를 준비하세요.</p><p class="small-note">${s.history.filter(h=>h.kind==='portfolio-selection').slice(-1).map(h=>`최근 신청: ${h.awarded?'선정':'미선정'} · ${h.years}년`).join('')}</p></div></details>`;}
function report(){const r=s.lastReport;if(!r)return '';const outcomes={completed:t('수행','Completed'),rested:t('충분히 쉬었다','Recovered'),talked:t('이야기를 나눴다','Talked together'),missed:t('수행하지 못했다','Could not complete'),failed:t('결과를 얻지 못했다','No result'),presented:t('학술 발표','Presented'),attended:t('청강·교류','Attended'),unprepared:t('발표를 준비하지 못했다','Not ready to present'),success:t('진척','Progress'),progress:t('연구 진척','Research progress'),recovered:t('충분히 쉬었다','Recovered'),not_completed:t('계획을 수행하지 못했다','Could not complete the plan'),inconclusive:t('유의미한 결과를 얻지 못했다','Inconclusive result'),preparing:t('발표 준비가 더 필요했다','Needs further preparation')};return `<details class="month-report"><summary>${t('지난달 수행 보고','Last month’s report')}<span>${r.results.filter(x=>x.performed).length} / 4 ${t('주 수행','weeks carried out')} · ${r.published?t('논문 게재','Paper published'):t('펼쳐서 확인','Open to inspect')}</span></summary><ol>${r.results.map((w,i)=>`<li><span>${i+1}${t('주차',' week')}</span><strong>${esc(activityName(w.proposed))}</strong><em>${outcomes[w.outcome]||(w.performed?t('계획 수행','Carried out'):t('계획 변경·미수행','Changed / not completed'))}</em></li>`).join('')}</ol></details>`;}
const feedbackOptions={praise:[['칭찬한다','Praise'],['지난달 잘한 점을 구체적으로 인정합니다.','Recognize last month’s work.']],listen:[['넘어간다','Move on'],['추가 평가 없이 이번 달 계획을 의논합니다.','Discuss the next plan without further evaluation.']],critique:[['지적한다','Critique'],['지난달의 병목과 보완할 부분을 짚습니다.','Discuss what needs improvement.']]};
function policyControls(){const p=s.policies??DEFAULT_POLICIES;return `<fieldset class="advising-policies"><legend>이번 달 지도 방침</legend><label>워라벨 · 출근 방식<select data-policy="work">${Object.entries(WORK_POLICIES).map(([id,label])=>`<option value="${id}" ${p.work===id?'selected':''}>${label}</option>`).join('')}</select></label><label>공부와 연구의 균형<select data-policy="study">${Object.entries(STUDY_POLICIES).map(([id,label])=>`<option value="${id}" ${p.study===id?'selected':''}>${label}</option>`).join('')}</select></label><p class="small-note">매달 면담에서 조정합니다. 긴 일정에는 피로가 쌓일 수 있습니다.</p></fieldset>`;}
function schedule(){const proposed=proposeSchedule(s),total=Object.values(s.allocation).reduce((a,b)=>a+b,0),enough=affordable()&&!(s.facultyAction==='funding'&&!canApplyGrant(s,grantApplication.role)),shared=s.professorGender!=='unspecified'&&s.professorGender===s.gender;return `<section class="schedule monthly-schedule"><div class="section-top"><h2>${t('주별 지도계획','Weekly advising plan')}</h2><span>${t('한 달에 네 주 · 학생의 제안을 수정합니다.','Four weeks per month · discuss and revise the proposal.')}</span></div>${isFestival()?`<div class="festival-notice"><strong>${monthName(s.month)} ${t('셋째 주 학술대회','conference · week 3')}</strong><span>${t('1·2주 준비 → 3주 발표·청강 → 4주 회복','Prepare in weeks 1–2 → present or attend in week 3 → recover in week 4')}</span></div>`:''}<div class="weekly-planner">${s.plan.map((id,i)=>`<div class="week-plan"><div class="week-heading"><strong>${i+1}${t('주차',' week')}</strong><span>${isFestival()&&i===2?t('고정 학술대회','Fixed conference'):t('논의 후 조정','Discuss & adjust')}</span></div><p class="proposal">${t('학생 제안','Student proposes')}<br><strong>${activityName(proposed[i])}</strong></p><label for="week-${i}">${t('합의한 일정','Agreed schedule')}</label><select id="week-${i}" data-week="${i}" ${isFestival()&&i===2?'disabled':''}>${Object.entries(ACTIVITIES).map(([key,a])=>`<option value="${key}" ${id===key?'selected':''}>${activityName(key)}</option>`).join('')}</select><p class="week-desc">${activityDescription(id)}</p></div>`).join('')}</div>${policyControls()}<div class="meeting-feedback"><div class="section-top"><h3>${t('이번 면담의 연구 피드백','Feedback at this meeting')}</h3><span>${t('지난달의 수행 보고를 바탕으로','Based on last month’s report')}</span></div><div class="feedback-options">${Object.entries(feedbackOptions).map(([id,txt])=>`<label class="feedback-option ${s.feedback===id?'selected':''}"><input type="radio" name="feedback" value="${id}" ${s.feedback===id?'checked':''}><strong>${txt[0][lang==='ko'?0:1]}</strong><span>${txt[1][lang==='ko'?0:1]}</span></label>`).join('')}</div></div><section class="faculty-credit-panel"><fieldset><legend>${t('교수의 업무 배분','Faculty workload allocation')}</legend><p>${t(`이번 달 ${facultyCapacity(s).credits}크레딧을 네 업무에 나눕니다.`,`Divide ${facultyCapacity(s).credits} monthly workload units.`)}</p>${Object.entries(s.allocation).map(([k,n])=>`<label class="allocation-row"><span>${facultyLabel(k)}</span><input type="number" min="0" max="${facultyCapacity(s).credits}" step="1" data-allocation="${k}" value="${n}" aria-label="${facultyLabel(k)} ${t('크레딧','workload units')}"></label>`).join('')}<p class="workload-context">${facultyCapacity(s).sabbatical?'연구년 · 교육 의무 일시 해제':facultyCapacity(s).vacation?'방학 · 교육 유지 부담 완화':'학기 중 · 교육을 우선 배정해 주세요.'} · 업무 반영 ${Math.round(facultyCapacity(s).efficiency*100)}%${facultyCapacity(s).jitter?' · 일정 변동 '+(facultyCapacity(s).jitter>0?'+':'')+facultyCapacity(s).jitter+'크레딧':''}</p><p id="allocation-total" class="${total!==facultyCapacity(s).credits?'danger-text':''}">${t('합계','Total')} ${total} / ${facultyCapacity(s).credits}</p></fieldset></section><details class="management-controls"><summary>${t('교수 업무·연구실 예산 조정','Adjust faculty workload & lab budget')}<span>${t('예산과 업무 배분은 다음 달에도 유지됩니다.','Allocations carry forward to the next month.')}</span></summary><div class="management-grid"><fieldset><legend>${t('연구비 집행 계획','Research expenditure')}</legend><p>${t('매달 인건비와 집행 계획을 함께 확인합니다.','Game budget · stipend discussed at each meeting')}</p><label class="budget-row"><span>${t('학생인건비 계상률','Stipend allocation rate')}</span><input type="number" data-budget="salary" min="0" max="100" step="1" value="${s.lab.budget.salary}" aria-label="학생인건비 계상률"></label><p id="stipend-amount">${t('학생인건비','Monthly stipend')} ${currency(salaryBase()*s.lab.budget.salary/100)}</p>${[['environment',t('연구환경','Research environment')],['performance',t('연구성과 지원','Research support')],['publicity',t('대외홍보','Public outreach')]].map(([k,label])=>`<label class="budget-row"><span>${label}</span><input type="number" min="0" max="6" step="1" data-budget="${k}" value="${s.lab.budget[k]}" aria-label="${label}"></label>`).join('')}<p id="expense-amount">${t('이번 달 예상 지출','Estimated expenditure')} ${currency(estimate())}</p></fieldset></div><div class="faculty-special"><p class="abstract-status">해외학회: ${({none:'방학 첫 달에 초록을 제출할 수 있습니다.',review:'초록 심사 중',accepted:'초록 채택 · 연구비와 이번 달 일정을 확인해 주세요.',rejected:'이번 초록은 미채택 · 다음 학회에서 다시 도전할 수 있습니다.',attended:'발표와 교류를 마쳤습니다.',expired:'이번 학회는 참석하지 않고 다음 기회를 준비합니다.'})[s.travel?.status??'none']}</p><label for="faculty-action">${t('이번 달 교수의 추가 활동','Additional faculty activity')}</label><select id="faculty-action"><option value="routine" ${s.facultyAction==='routine'?'selected':''}>${t('평소의 학술·교육 활동','Routine scholarship & teaching')}</option>${[1,7].includes(calendarMonth(s.month))&&s.month>=24?`<option value="abstract" ${s.facultyAction==='abstract'?'selected':''}>해외학회 초록 투고 · 다음 달 채택 결과</option>`:''}<option value="report" ${s.facultyAction==='report'?'selected':''}>연차보고서 작성·산학협력단 정산 준비</option><option value="funding" ${s.facultyAction==='funding'?'selected':''}>${t('연구비 신청 · 제안서 제출','Apply for additional funding')}</option><option value="recommend" ${s.facultyAction==='recommend'?'selected':''}>${t('추천서 쓰기 · 논문 게재 후 1년에 1회 인정','Write a recommendation · once a year after publication')}</option><option value="support" ${s.facultyAction==='support'?'selected':''}>${t('학생 지원·원격 면담 강화','Extra student support / remote advising')}</option>${isBreak()&&canTravel(s)?`<optgroup label="${t('방학 중 해외학회','Overseas conference during break')}"><option value="abroad_student" ${s.facultyAction==='abroad_student'?'selected':''}>${t('학생만 보내기','Send the student')} · ${currency(18)}</option><option value="abroad_together" ${s.facultyAction==='abroad_together'?'selected':''}>${t('같이 가기 · 방 2개','Travel together · 2 rooms')} · ${currency(34)}</option>${shared?`<option value="abroad_shared" ${s.facultyAction==='abroad_shared'?'selected':''}>${t('같이 가기 · 같은 숙소 방 1개','Travel together · 1 shared room')} · ${currency(26)}</option>`:''}</optgroup>`:''}</select>${isBreak()&&shared?`<label class="consent"><input id="travel-consent" type="checkbox" ${travelConsent?'checked':''}>${t('같은 방을 사용할 경우 학생의 동의를 확인했습니다.','The student agrees to share a room if that option is chosen.')}</label>`:''}</div></details><div class="monthly-confirm"><div><strong>${t('이번 달 예상 지출','Estimated monthly cost')} <span id="confirm-cost">${currency(estimate())}</span></strong><span>${t('일정 수행은 체력·의욕·관계에 따라 달라집니다.','Execution depends on energy, motivation and trust.')}</span></div><button class="primary" data-ui="advance" ${busy||!validateSave(s)||total!==facultyCapacity(s).credits||!enough?'disabled':''}>${t('일정 확정 · 한 달 진행','Agree & advance one month')} →</button></div><p class="budget-error ${enough?'hidden':''}" id="budget-error">${t('현재 잔액으로 이 계획을 집행할 수 없습니다. 운영비 또는 여행 계획을 조정하세요.','This plan exceeds available funds. Adjust operations or travel.')}</p></section>`;}
function welcome(){
  const fieldOptions=[...new Set(DISCIPLINES.map(d=>d.group))].map(group=>`<optgroup label="${esc(group)}">${DISCIPLINES.filter(d=>d.group===group).map(d=>`<option value="${d.id}" ${d.id==='050'?'selected':''}>${esc(d.label)}</option>`).join('')}</optgroup>`).join('');
  return `<section class="welcome"><h2>첫 지도학생이 찾아왔습니다.</h2><p>응원하고 함께 배우는 여덟 번의 봄.</p><form id="start-form">
    <fieldset class="professor-setup"><legend>교수님의 연구실</legend><div class="setup-grid">
      <label>교수님 이름<input name="professorName" maxlength="40" value="지도교수" required autocomplete="off"></label><label>성별<select name="professorGender"><option value="female">여성</option><option value="male" selected>남성</option><option value="other">기타</option></select></label>
      <label>연령 (30–55)<input type="number" name="professorAge" min="30" max="55" value="38" required inputmode="numeric"></label>
      <label>연구 분야<select name="fieldId" id="field-id">${fieldOptions}</select></label>
      <label>연구 방식<select name="labMode" id="lab-mode"><option value="dry">Dry lab · 이론·계산</option><option value="wet">Wet lab · 실험</option></select></label>
      <label>소속학교<select name="institution"><option value="national">국립대</option><option value="private">사립대</option><option value="institute">과학기술원 · 초보자 모드</option></select></label>
    </div><p id="profile-hint" class="small-note">국립대 · 안정적인 지원과 행정 절차</p></fieldset>
    <div class="first-contact">${portrait()}<div><span>첫 지도학생 · ${genderName(s.gender)}</span><strong id="assigned-name">${esc(name())}</strong><small>이름과 성별은 자동 배정됩니다.</small></div></div>
    <div class="telemetry-choice"><label><input type="checkbox" id="analytics-consent" ${analyticsConsent()?'checked':''}> 익명 게임기록 제공을 위한 기기 내 기록에 동의합니다 (선택).</label><details class="consent-details"><summary>기록 범위·보관 안내</summary><small>제작자 김가현의 게임 밸런스 분석용: 무작위 실행 ID·월별 선택·가상 파라미터·엔딩. 실제 이름·연락처는 제외합니다. 일반 플레이어의 기록은 직접 내보내기 전까지 이 기기에만 남습니다. 제공된 서버 기록은 90일 보관하며, 거부해도 플레이할 수 있습니다.</small></details></div><button class="primary" type="submit">첫 면담 시작 →</button></form><p class="small-note">매달 면담과 주별 계획으로 함께 자랍니다.</p></section>`;
}
function updateProfileSetup(){const d=getDiscipline($('#field-id').value),lab=$('#lab-mode'),before=lab.value;lab.innerHTML=d.labModes.map(m=>`<option value="${m}">${m==='dry'?'Dry lab · 이론·계산':'Wet lab · 실험'}</option>`).join('');if(d.labModes.includes(before))lab.value=before;lab.disabled=false;const institution=$('select[name="institution"]').value;$('#profile-hint').textContent=({national:'국립대 · 안정적인 지원과 행정 절차',private:'사립대 · 연구실 운영의 자율성',institute:'과학기술원 · 넉넉한 지원과 업무 보조'})[institution];}

const choice=(value,title,body='',disabled=false)=>`<button class="choice" data-ui="decide" data-choice="${value}" ${disabled?'disabled':''}><strong>${title}</strong>${body?`<span>${body}</span>`:''}</button>`;
function pending(){const p=s.pending;if(!p)return '';let heading='',body='',buttons='';
if(p.kind==='event'){const e=EVENTS.find(e=>e.id===p.id);heading=e.title[lang];body=e.body[lang];buttons=e.options.map((o,i)=>choice(i,o.label[lang])).join('');}
if(p.kind==='route'){heading=t('학부 졸업, 진학의 갈림길','Graduation. A choice about graduate school.');body=canContinue(s)?t('두 해 동안 연구실에서 함께했다. 학생은 이제 다음 몇 해의 이야기를 꺼낸다.','You have spent two years together in the lab. Your student begins to talk about the years ahead.'):t('학생은 대학원에 남지 않기로 했다. 다른 길을 선택하는 마음을 먼저 듣는다.','Your student has chosen not to stay. Listen to what they want from a different path.');buttons=choice('masters',t('석사 → 박사','Master’s → PhD'),t('석사과정 후, 박사 진학을 다시 의논합니다.','Revisit the PhD decision after a master’s.'),!canContinue(s))+choice('integrated',t('석박사통합','Integrated MS / PhD'),t('6년의 통합과정으로 연구를 이어갑니다.','Continue into a six-year integrated program.'),!canContinue(s))+choice('graduate',t('학사 졸업으로 마무리','Finish with a bachelor’s degree'));}
if(p.kind==='masters'){const requirements=degreeTargets(s.professorProfile?.fieldId,'masters'),ready=s.career.submissions>=requirements.submissions&&s.career.papers>=requirements.papers&&s.career.conferences>=requirements.conferences;heading=t('석사학위, 다음 학기의 계획','A master’s degree. Plans for next semester.');body=t(`석사과정 성과를 확인합니다. 논문 제출 ${requirements.submissions}개, 학술 발표 ${requirements.conferences}개가 필요합니다. 다음 학기의 계획을 함께 의논합니다.`,'The master’s requires one submission and one presentation. Discuss whether to continue, graduate, or take another semester to complete the work.');buttons=choice('continue',t('박사과정으로 진학','Continue to a PhD'),'',!ready||!canContinue(s))+choice('graduate',t('석사 졸업','Graduate with a master’s'),'',!ready)+(!ready&&!s.mastersExtended?choice('extend',t('한 학기 보완','Extend by one semester')):!ready?choice('graduate',t('학위를 마치지 못하고 과정 정리','Leave without completing the degree')):'');}
if(p.kind==='qual'){heading=t('박사 자격시험','The qualifying examination');body=t('학생은 그동안의 문헌과 연구 질문을 다시 정리했다. 지금 응시할지, 준비 시간을 더 확보할지 결정한다.','Your student has organized the literature and research questions. Decide whether to take the exam now or make room for more preparation.');buttons=choice('exam',t('자격시험에 응시','Take the examination'))+choice('prepare',t('준비 시간을 확보','Make time to prepare'),t('이번 달 공부와 휴식을 중심으로 다시 계획합니다.','Plan this month around study and recovery.'),s.qualPreparations>=2)+choice('graduate',t('과정을 정리하고 다른 길을 의논','Discuss leaving the program'));}
if(p.kind==='external-admission'){heading='다른 학교에서 이어 갈 연구';body=`“교수님, 제 연구를 보고 ${p.level==='bachelor'?'다른 대학원 석사과정':'해외 박사과정'}에 지원해 보라는 연락을 받았습니다. 새로운 환경에서도 배워 보고 싶어요.”`;buttons=choice('encourage','진학을 응원한다','함께 지원을 준비하고 지금까지의 지도를 마무리합니다.')+choice('remain','잔류를 권유한다','이 연구실에서 이어 갈 수 있는 연구와 지원을 제안합니다.');}
if(p.kind==='sabbatical'){heading=t('교수의 연구년','Your sabbatical year');body=t('5년차를 앞두고 연구년이 시작된다. 자리를 비우더라도 면담과 수업, 행정의 연결을 준비해야 한다.','Your sabbatical begins as year five approaches. Being away still requires a plan for meetings, teaching and administration.');buttons=choice('home',t('국내에서 연구 · 지도 유지','Research at home; keep advising'),t('교수의 연구 시간과 일상 지도를 함께 확보합니다.','Protect research time while keeping the daily connection.'))+choice('away',t('해외 방문연구 · 원격 지도','Visit a lab abroad; advise remotely'),t('원격 면담을 챙기지 않으면 학생과의 거리가 벌어질 수 있습니다.','Keep remote meetings going, or distance may grow.'));}
if(p.kind==='service'||p.kind==='service-review'){heading=t(p.kind==='service'?'전문연구요원 선발 준비 상담':'학위 후 복무 계획 점검','Academic planning');body=p.kind==='service'?t('학생이 박사 진학과 병역 계획을 함께 묻는다. 지정 자연계 대학원 여부, 선발 일정과 자격은 소속 대학과 병무청에서 확인해야 한다. 상담은 자동 선발이나 병역 해결을 뜻하지 않는다.','Discuss academic plans and next steps.'):t('박사학위 이후 연구 현장과 복무 계획을 함께 점검한다. 2023년 이후 편입자의 학위 취득·후속 복무 규정을 확인하며, 연구실 밖의 계획을 준비한다.','Review plans after the doctorate.');buttons=choice('consult',t('소속 대학과 공식 안내를 함께 확인','Review the official guidance together'))+choice('skip',t('현재 병역 계획을 유지','Keep the current plan'));}
if(p.kind==='defense'){heading=t('여덟 번째 학년의 끝, 학위 심사','The end of year eight. The defense.');body=canDefend(s)?t('논문과 발표, 자격시험의 기록이 모였다. 이제 학생은 자기 이름으로 연구실 밖에 나선다. 그리고 다시 몇 해가 지나, 메일 한 통이 도착한다.','Papers, presentations and an examination are complete. Your student steps beyond the lab under their own name. A few years later, a letter arrives.'):t('학위요건을 아직 다 채우지 못했다. 8년의 지도 기간이 끝나 학위 심사를 마칠 수 없다.','The degree requirements are not all complete. The game’s eight years end; a person’s next plan does not.');buttons=choice('defend',t(canDefend(s)?'심사, 그리고 몇 해 후의 메일':'학위 심사 결과 확인','The defense, then a letter years later'));}
return `<section id="decision" class="decision"><div class="decision-label">${t('연구실에서 생긴 일','A moment in the lab')}</div><h2>${heading}</h2><p>${body}</p><div class="choices">${buttons}</div>${p.kind.startsWith('service')&&lang==='ko'?'<p class="small-note"><a href="https://www.mma.go.kr/contents.do?mc=mma0000765" target="_blank" rel="noopener">병무청 전문연구요원 복무 안내 ↗</a></p>':''}</section>`;}
function lab(){if(!s.started)return welcome();return `<div class="lab-layout">${sidebar()}<div class="lab-main"><div class="term-heading"><div><p>${phase()} · ${semester(s.month)}</p><h2>${s.ending?t('그 후의 이야기','The story after'):calendar(s.month)}</h2></div><span class="term-count">${s.month} / 96 ${t('개월','months')}</span></div>${progress()}<div class="student-voice"><p>${s.ending?t(s.ending==='gameover'?'함께한 시간을 정리할 때가 왔다.':'한 사람의 다음 이야기가 시작되었다.','Their next story has begun.'):esc(studentLine(s,lang))}</p><span>― ${esc(name())}</span></div>${s.crisis&&!s.ending?`<div class="notice error" role="alert"><strong>${t('다음 계획을 함께 의논할 때입니다.','Do not postpone the next conversation.')}</strong><p>${t('학생이 계획을 이어가기 어려워합니다. 일정을 조정하고 어떤 지원을 원하는지 물어보세요. 과정을 계속할지 결정할 시간도 함께 확보합니다.','Your student is struggling to continue. Without room for rest and conversation, they may leave next month.')}</p></div>`:''}${Object.values(s.professor).some(n=>n<15)&&!s.ending?`<div class="notice warning"><strong>${t('교수의 업무 균형을 회복해야 합니다.','Your faculty workload needs attention.')}</strong><p>${t('업무 배분에서 낮아진 영역에 시간을 배정하세요. 어느 영역이든 0이면 운영이 종료됩니다.','Allocate time to the neglected area. Any area reaching zero ends lab operations.')}</p></div>`:''}${s.ending?`<section class="ending-summary"><span>${endingType(s.ending)}</span><h2>${endingMeta({ending:s.ending,endingReason:s.endingReason}).title[lang]}</h2><p>${endingMeta({ending:s.ending,endingReason:s.endingReason}).career[lang]}</p><p>${endingMeta({ending:s.ending,endingReason:s.endingReason}).time[lang]}</p><button class="primary" data-ui="read-current">${s.ending==='gameover'?'종료 기록 확인':t('도착한 메일 읽기','Read the letter that arrived')} →</button>${s.ending!=='gameover'?'<button class="secondary" data-ui="view-current-cv">연구자 CV 보기</button>':''}<button class="secondary" data-ui="current-statistics">파라미터 보기</button><button class="secondary" data-ui="new">${t('다시 시작','Start again')}</button></section>`:!s.started?welcome():s.pending?pending():`${project()}${grantPanel()}${report()}${schedule()}`}</div></div>`;}
function journal(){const entries=s.history.filter(x=>['month','event','route','promotion','qual','sabbatical','submission','paper','conference','recommendation','ending','conference-festival','research-travel','annual-grant','grant-report','grant-report-delay','grant-application','grant-selection','portfolio-selection','portfolio-payment','external-admission','abstract-submission','abstract-decision','abstract-window-closed'].includes(x.kind)).slice(-180).reverse();return `<section class="content-row"><h2>${t('연구실 기록','Lab notebook')}</h2><div><p class="intro-note">${t('계획과 수행은 다를 수 있습니다. 면담·프로젝트·학위의 기록을 함께 봅니다.','Plans and actions can differ. Read the record of meetings, projects and degrees.')}</p>${entries.length?`<ol class="journal-list">${entries.map(h=>{let title='',body='';if(h.kind==='abstract-submission'){title='해외학회 초록 투고';body=`프로젝트 ${h.projectId}`;}else if(h.kind==='abstract-decision'){title=h.accepted?'해외학회 초록 채택':'해외학회 초록 미채택';body='심사 결과가 도착했다.';}else if(h.kind==='abstract-window-closed'){title='다음 해외학회를 준비하며';body='이번 학회 참석 기간을 마무리했다.';}else if(h.kind==='portfolio-selection'){title=h.awarded?'새 연구과제 선정':'연구과제 미선정';body=`${h.role==='pi'?'책임연구':'공동참여'} · ${h.years}년`;}else if(h.kind==='portfolio-payment'){title='과제 연차 연구비 입금';body=currency(h.amount);}else if(h.kind==='external-admission'){title=h.choice==='encourage'?'외부 진학 지원':'연구실 잔류 상담';body='다음 연구 환경을 함께 의논했다.';}else if(h.kind==='month'){title=(Array.isArray(h.plan)?h.plan:[]).map(activityName).join(' · ');body=t(`네 주 중 ${(Array.isArray(h.results)?h.results:[]).filter(r=>r?.performed).length}주 수행`,`Carried out ${(Array.isArray(h.results)?h.results:[]).filter(r=>r?.performed).length} of four weeks`);}else if(h.kind==='event'){const e=EVENTS.find(e=>e.id===h.id);title=e?.title[lang];body=e?.options[h.choice]?.label[lang];}else if(h.kind==='ending'){title=ENDINGS[h.ending]?.title?.[lang]||'기록';body=ENDINGS[h.ending]?.career?.[lang]||'';}else{title=({route:t('대학원 진학','Graduate admission'),promotion:t('박사과정 진학','Entered the PhD program'),qual:t(h.passed?'자격시험 통과':'자격시험 재응시 준비',h.passed?'Qualifying exam passed':'Preparing an exam retake'),sabbatical:t('교수 연구년 시작','Faculty sabbatical began'),submission:t('논문 제출','Manuscript submitted'),paper:t('논문 게재','Paper accepted'),conference:t('학술 발표','Conference presentation'),recommendation:t('추천서 발송','Recommendation sent'),'conference-festival':t('정기 학술대회','Scheduled conference'),'research-travel':t('해외학회','Overseas conference'),'grant-report':'연차보고서 제출','grant-report-delay':'연차보고 지연','grant-application':'후속 과제 신청','grant-selection':h.awarded?'후속 과제 선정':'후속 과제 미선정·교내 공백지원','annual-grant':t('연구비 연례 지원','Annual research funding')}[h.kind]);if(h.kind==='annual-grant')body=currency(h.amount);if(h.kind==='research-travel')body=t(`숙박 ${h.rooms||1}개 방`,`Lodging: ${h.rooms||1} room(s)`);}return `<li><time>${calendar(Math.max(0,h.month-1))}</time><div><h3>${esc(title)}</h3>${body?`<p>${esc(body)}</p>`:''}</div></li>`;}).join('')}</ol>`:`<div class="empty-state"><h3>${t('아직 첫 장입니다.','The first page is still blank.')}</h3><p>${t('첫 면담 뒤, 함께 보낸 한 달의 기록이 남습니다.','Complete your first month to begin the notebook.')}</p><a class="primary link-button" href="#lab">${t('학생 지도하러 가기','Go to advising')} →</a></div>`}</div></section>`;}
function letters(){return `<section class="content-row"><h2>${t('도착한 메일','Letters received')}</h2><div><p class="intro-note">${t('연구실에서 함께한 시간이 흘렀다. 그리고 다시 몇 해가 지나, 메일이 도착했다.','An undergraduate researcher, then a graduate student. Eight years had passed. And then, a few more.')}</p><div class="student-record-grid">${gallery.map(entry=>`<article class="student-record"><h3>${esc(entry.name)}</h3><p>${ENDINGS[entry.ending].career[lang]} · ${entry.month}개월</p><button class="secondary" data-ui="read-entry" data-entry="${esc(entry.id)}">후일담 메일</button>${entry.cv?`<button class="secondary" data-ui="record-cv" data-entry="${esc(entry.id)}">학생 CV</button>`:''}</article>`).join('')}</div><div class="letter-grid">${Object.entries(ENDINGS).map(([id,e])=>{const entry=gallery.find(x=>x.ending===id);return `<button class="letter-card ${entry?'unlocked':'locked'}" data-ui="read" data-ending="${id}" ${entry?'':'disabled'}><span class="envelope-icon" aria-hidden="true">${entry?'✉':'—'}</span><span class="ending-type">${endingType(id)}</span><strong>${entry?e.title[lang]:t('아직 도착하지 않은 편지','A letter yet to arrive')}</strong><span>${id==='resident_researcher'&&!entry?'아직 알 수 없는 진로':e.career[lang]}</span><small>${entry?esc(entry.name)+' · '+entry.date:t('미발견','Undiscovered')}</small></button>`;}).join('')}</div><p class="small-note">${t('함께한 시간은 서로 다른 메일로 남습니다.','Shared time lives on in different letters.')}</p></div></section>`;}
const source=(label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
function portal(){return `<section class="portal-hero"><div><p class="portal-eyebrow">교수 업무 포털 · PROFESSOR MAKER</p><h1>한 학생의 다음 봄을<br>함께 준비하는 일.</h1><p>Professor Maker는 교수의 입장에서 연구실을 운영하고 한 명의 학생을 지도하는 <strong>경영 &amp; 육성 시뮬레이션</strong>입니다. 매달 연구 계획을 의논하고, 학생의 배움과 휴식, 연구실의 살림을 함께 돌보세요.</p><a class="primary" href="#lab">${s.started?'학생지도 이어하기':'학생지도 시작하기'} →</a><span class="portal-fiction">가상의 대학과 연구실을 배경으로 합니다.</span></div><div class="portal-office" aria-hidden="true"><div class="office-window"></div><div class="office-desk"></div>${portrait()}<span class="office-message">교수님, 잠깐 이야기할 수 있을까요?</span></div></section><div class="portal-cards"><article><span>01 · 학생 지도</span><h2>한 명의 학생, 여덟 번의 봄</h2><p>학부연구생의 첫 시행착오부터 대학원의 연구까지. 대사와 수행 보고를 읽으며 주별 계획을 함께 고칩니다.</p></article><article><span>02 · 연구실 운영</span><h2>연구만큼 중요한 살림</h2><p>연구비와 학생인건비, 환경과 교수 업무를 조절합니다. 한쪽으로 기울면 다른 곳에서도 신호가 옵니다.</p></article><article><span>03 · 그 후의 이야기</span><h2>각자의 길에서 도착한 메일</h2><p>졸업과 진학, 다양한 진로의 후일담을 만납니다. 함께 쌓은 성과와 추억은 학생별 CV로 남습니다.</p></article></div>`;}
function render(){const v=view(),titles={home:'교수 업무 포털',lab:t('학생 지도','Advisee management'),journal:t('연구 기록','Progress records'),letters:t('메일함','Alumni correspondence')};document.documentElement.lang=lang;document.body.dataset.locale=lang;document.body.dataset.onboarding=String(!s.started&&v==='lab');document.title=`Professor Maker — ${titles[v]}`;$('#app').innerHTML=`<a class="skip-link" href="#main">${t('본문 바로가기','Skip to content')}</a><div class="utility-bar"><div class="container"><span>${t('Professor Maker · 연구실 경영·육성','Professor Maker · Lab management')}</span><div><button data-ui="guide">${t('플레이 안내','Help')}</button><button data-ui="settings">${t('저장 관리','Save manager')}</button></div></div></div><header class="site-header"><div class="container header-content"><a class="brand" href="#home"><img src="./assets/lab-mark.svg" class="lab-brand-mark" alt="Professor Maker 로고"><span class="brand-name">Professor Maker<small>${t('연구실 경영·육성 시뮬레이션','Lab management & cultivation')}</small></span></a><nav class="header-nav" aria-label="${t('주 메뉴','Main navigation')}"><a href="#lab" ${v==='lab'?'aria-current="page"':''}>${t('연구실','My lab')}</a><a href="#journal" ${v==='journal'?'aria-current="page"':''}>${t('기록','Records')}</a><a href="#letters" ${v==='letters'?'aria-current="page"':''}>${t('메일','Alumni')}</a></nav></div></header><nav class="breadcrumb" aria-label="${t('현재 위치','Breadcrumb')}"><div class="container"><span>${t('홈','Home')}</span><span aria-hidden="true">›</span><strong aria-current="page">${titles[v]}</strong><span class="save-status">${storageOK?t('자동 저장 켜짐','Autosave on'):t('저장 불가 · 파일 내보내기 필요','Storage unavailable · export your save')}</span></div></nav>${s.started&&!s.ending&&v!=='home'?`<div class="faculty-scroll-summary"><strong>${esc(s.professorName||'지도교수')} · ${calendar(s.month)}</strong>${Object.entries(s.professor).map(([k,n])=>`<span>${facultyLabel(k)} ${Math.round(n)}</span>`).join('')}<a href="#lab">이번 달 지도계획</a></div>`:''}<main id="main" class="container" tabindex="-1"><div class="page-title"><h1>${titles[v]}</h1><button class="text-button" data-ui="print">${t('인쇄','Print')}</button></div><nav class="section-nav" aria-label="${t('게임 메뉴','Game navigation')}">${Object.entries(titles).filter(([id])=>id!=='home').map(([id,title])=>`<a href="#${id}" ${v===id?'aria-current="page"':''}>${title}<span aria-hidden="true">${v===id?'—':'→'}</span></a>`).join('')}</nav>${v==='home'?portal():v==='lab'?lab():v==='journal'?journal():letters()}</main><footer class="site-footer"><div class="container"><div><strong>Professor Maker</strong><p>${t('제작자: 김가현 · 한 명의 학생과 함께하는 8년','Concept & original letters by Gahyoun Gim · one student, eight years')}</p><small>${t('이 이야기는 픽션입니다. 등장인물과 기관·사건은 가상이며, 실존 대상과의 유사성은 우연입니다. · © 김가현 · GNU GPL v3','An independent fictional game. Korean presentation draws on GNU colors, typography and layout, with an original research lab logo.')}</small><p class="notice-links">진로·진학은 개인의 상황과 희망, 해당 기관의 공식 정보를 살펴 신중하게 결정하시기 바랍니다. 이 게임은 실제 진로 상담이나 제도 안내를 대신하지 않습니다.</p></div><a href="https://github.com/Gahyoun?tab=repositories" target="_blank" rel="noopener noreferrer">김가현의 GitHub 저장소 디렉토리 ↗</a></div></footer>`;}
function modal(html){const d=$('#modal');d.classList.remove('cv-modal','vn-modal');d.innerHTML=`<button class="modal-close" data-ui="close" aria-label="${t('닫기','Close')}">×</button>${html}`;if(!d.open)d.showModal();}
function guide(){modal(`<h2>${t('교수님의 첫 면담 안내','Your first advising meeting')}</h2><ol class="guide-list"><li>${t('매달 학생의 네 주 일정을 논의합니다. 학생 제안과 합의한 계획은 실제 수행과 다를 수 있습니다.','Discuss four weekly activities each month. Proposals and agreed plans may differ from what actually happens.')}</li><li>${t('학생의 능력과 성격은 숨겨져 있습니다. 대사·수행보고·연구성과에서 관찰하세요.','Abilities and personality are hidden. Observe dialogue, reports and research outcomes.')}</li><li>${t('지난달 연구 보고에 맞는 칭찬·지적을 선택하세요. 이유 없는 칭찬이나 근거 없는 지적은 역효과를 냅니다.','Match praise and critique to last month’s evidence. Empty praise or unwarranted criticism can backfire.')}</li><li>${t('학술활동·교육·행정·학생관리 중 어느 업무가 0이면 게임이 끝납니다. 업무칸 합계를 8로 배분하세요.','Any faculty responsibility reaching zero ends the game. Allocate eight workload units.')}</li><li>${t('매달 면담에서 인건비 계상률·출근 방식·공부와 연구의 균형을 조정합니다.','Adjust stipend rates in the first month of each academic year. Environment, support and outreach can change monthly.')}</li><li>${t('4월·10월 셋째 주는 학술대회입니다. 앞의 두 주에 준비하고 마지막 주에 쉬는 계획도 가능합니다.','Week three of April and October is a conference. Prepare beforehand and rest afterward.')}</li><li>${t('2년 뒤 진학, 석사학위와 qual, 5년차 교수 연구년이 찾아옵니다. 학생이 힘들다는 신호를 보내면 다음 달까지 방치하지 마세요.','Admission follows two years, then degree reviews, qual and a year-five sabbatical. Do not ignore warning signs until the next month.')}</li><li>${t('졸업 이후의 진로와 편지는 다양합니다. 대학 교수로 다시 만나는 이야기에는 별도의 조건이 있으며, 각자의 선택과 생활은 서로 다른 후일담으로 남습니다.','Careers and letters vary after graduation. Becoming a fellow professor has its own requirements. Each person’s choices and life have their own epilogue.')}</li></ol><div class="help-foot"><p>${t('면담과 주요 선택을 따라 약 15분 동안 진행합니다.','Play through meetings and decisions in about fifteen minutes.')}</p><p>${t('모바일: Safari 공유 → 홈 화면에 추가 / Chrome 메뉴 → 앱 설치. 첫 온라인 방문 후 오프라인 플레이가 가능합니다.','Mobile: Safari Share → Add to Home Screen / Chrome menu → Install app. Play offline after the first online visit.')}</p>${installPrompt?'<button class="primary" data-ui="install">'+t('앱 설치','Install app')+'</button>':''}</div>`);}
function settings(){modal(`<h2>${t('저장 관리','Save manager')}</h2><p>${t('현재 게임과 편지함을 JSON으로 보관하거나 기기 사이에서 옮깁니다. 저장은 이 브라우저에만 남습니다.','Export your game and letters as JSON to keep them or move between devices. Autosaves stay in this browser.')}</p><div class="settings-buttons"><button class="primary" data-ui="export">${t('저장 파일 내보내기','Export save')}</button><button class="secondary" data-ui="import">${t('저장 파일 불러오기','Import save')}</button><input type="file" id="import-file" accept="application/json,.json" hidden><button class="secondary" data-ui="new">${t('새 학생으로 시작','Start with a new student')}</button></div><label class="consent"><input type="checkbox" id="fast-mode" ${fast?'checked':''}>${t('빠른 진행 · 주간 결과 애니메이션 생략','Fast mode · skip weekly transition animation')}</label><div class="telemetry-choice"><label><input id="analytics-consent" type="checkbox" ${analyticsConsent()?'checked':''}> 익명 게임기록 보관 동의 (선택)</label><small>월별 선택·게임 파라미터·엔딩을 분석용으로 기기에 기록합니다. 일반 플레이어의 기록은 자동 전송되지 않습니다. 내보내기로 제작자에게 제공할지 직접 결정할 수 있습니다. 동의를 해제하면 기기 내 분석 기록이 삭제됩니다.</small><button class="secondary" data-ui="export-analysis">익명 분석 기록 내보내기</button><p class="telemetry-status">${esc(analyticsStatus())}</p></div><p class="small-note">${t('새로 시작해도 발견한 메일은 보관됩니다.','Starting again preserves discovered letters.')}</p>`);}
function openLetter(entry){if(!entry)return;letter=entry;page=0;showLetter();}
function endingMeta(entry){const original=ENDINGS[entry.ending];if(entry.ending!=='gameover')return original;const description=({graduation_requirements:['졸업 준비 미완료','학위요건 미충족'],time_limit:['마지막 학기의 끝','8년 내 학위 미완료'],qual_failure:['다음 길을 의논하다','자격시험 미통과']})[entry.endingReason];return description?{...original,title:{...original.title,ko:description[0]},career:{...original.career,ko:description[1]},time:{...original.time,ko:'지도 기간의 마지막 기록'}}:original;}
function endingPages(entry=letter){return getEndingPages(entry.ending,lang,entry.relationship,undefined,entry.endingReason,entry.memories||[]);}
function credits(){return `<section class="ending-credits"><p>PROFESSOR MAKER</p><h3>제작자: 김가현</h3><a href="https://github.com/Gahyoun?tab=repositories" target="_blank" rel="noopener noreferrer">GitHub 저장소 디렉토리 ↗</a><p>함께한 시간은 각자의 다음 이야기로 이어집니다.</p></section>`;}
function showLetter(){const e=endingMeta(letter),pages=endingPages(),body=pages[page].replaceAll('{name}',letter.name),isMail=/교수님께\.|Dear Professor,/.test(body),last=page===pages.length-1;
 modal(`<div class="letter-reader visual-novel"><div class="vn-scene ${isMail?'vn-mail':'vn-memory'}" aria-label="${isMail?'메일이 도착한 교수의 책상':'연구실을 돌아보는 장면'}"><div class="vn-window"><i></i><i></i></div><div class="vn-desk"><span class="vn-screen">${isMail?'새 메일 1통':'함께한 기록'}</span><span class="vn-cup"></span></div><div class="vn-scene-caption">${e.time[lang]}</div></div><div class="vn-text"><div class="letter-meta">${endingType(letter.ending)}<span>${e.career[lang]}</span></div><h2>${e.title[lang]}</h2><p class="letter-time">${isMail?`보낸 사람: ${esc(letter.name)} · 받는 사람: 지도교수`:'지도교수의 회상'}</p><div class="letter-paper" aria-live="polite">${body.split('\n\n').map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('')}</div><div class="letter-pagination"><button class="secondary" data-ui="prev-page" ${page===0?'disabled':''}>← 이전</button><span>${page+1} / ${pages.length}</span>${!last?'<button class="primary" data-ui="next-page">다음 →</button>':letter.ending!=='gameover'?'<button class="primary" data-ui="view-cv">함께한 기록 보기 →</button>':'<button class="primary" data-ui="finish-letter">종료 기록 보관</button>'}</div>${last?`${credits()}${letter.statistics?'<button class="secondary" data-ui="view-statistics">종료 시점 파라미터 보기</button>':''}`:''}</div></div>`);$('#modal').classList.add('vn-modal');$('#modal').scrollTop=0;}
let activeCV=null;
async function showCV(entry){
  if(!entry||entry.ending==='gameover')return;
  if(!entry.cv&&entry.ending===s.ending&&entry.name===s.name)await archive();
  if(!entry.cv){toast('이전 버전의 메일에는 CV 기록이 없습니다.');return;}
  busy=true;try{const result=await runEngine('cv-render',{model:entry.cv});activeCV=result;activeCV.css=await fetch("./cv.css").then(r=>r.text());modal(`<div class="cv-actions"><button class="secondary" data-ui="download-cv">CV 파일 저장</button><button class="secondary" data-ui="print-cv">인쇄 · PDF 저장</button><button class="primary" data-ui="finish-letter">기록을 서랍에 넣기</button></div>${result.html}`);$('#modal').classList.add('cv-modal');$('#modal').scrollTop=0;}catch(error){toast('CV를 불러오지 못했습니다. 다시 시도해 주세요.');}finally{busy=false;}
}
function downloadCV(){if(!activeCV)return;const documentHTML=`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(activeCV.model.name)} · 연구자 CV</title><style>${activeCV.css||''}</style><body>${activeCV.html}</body></html>`;const url=URL.createObjectURL(new Blob([documentHTML],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='professor-maker-cv.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function newGame(){modal(`<h2>${t('새로운 이야기를 시작할까요?','Begin a new story?')}</h2><p>${t('현재 게임을 새 게임으로 바꿉니다. 발견한 메일은 보관됩니다.','Replace the current run. Discovered letters are kept.')}</p><div class="settings-buttons"><button class="secondary" data-ui="export">${t('먼저 내보내기','Export first')}</button><button class="primary" data-ui="confirm-new">${t('새 게임 시작','Begin new game')}</button></div>`);}
function exportSave(){if(!validateSave(s)){toast(t('업무 배분과 예산을 올바르게 조정한 뒤 내보내 주세요.','Complete a valid allocation and budget before exporting.'));return;}const url=URL.createObjectURL(new Blob([JSON.stringify({format:'professor-maker',version:VERSION,state:s,gallery},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='professor-maker-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('저장 파일을 내보냈습니다.','Save exported.'));}
function updateCosts(){const total=Object.values(s.allocation).reduce((a,b)=>a+b,0),cost=estimate();if($('#allocation-total')){$('#allocation-total').textContent=t('합계 ','Total ')+total+' / '+facultyCapacity(s).credits;$('#allocation-total').classList.toggle('danger-text',total!==facultyCapacity(s).credits);}if($('#stipend-amount'))$('#stipend-amount').textContent=t('학생인건비 ','Monthly stipend ')+currency(salaryBase()*s.lab.budget.salary/100);if($('#expense-amount'))$('#expense-amount').textContent=t('이번 달 예상 지출 ','Estimated expenditure ')+currency(cost);if($('#confirm-cost'))$('#confirm-cost').textContent=currency(cost);if($('#budget-error'))$('#budget-error').classList.toggle('hidden',affordable());const b=$('[data-ui="advance"]');if(b)b.disabled=busy||!validateSave(s)||total!==facultyCapacity(s).credits||!affordable()||s.facultyAction==='funding'&&!canApplyGrant(s,grantApplication.role);}
function errorMessage(error){const m=error.message;return m.includes('accepted abstract')?t('초록이 채택된 뒤 참석할 수 있습니다.','An accepted abstract is required.'):m.includes('Abstract submission')?t('대학원부터 방학 첫 달에 초록을 투고할 수 있습니다.','Submit an abstract at the start of graduate vacation.'):m.includes('salary')||m.includes('Stipend')?t('학생인건비 계상률은 0–100의 정수로 선택하세요.','Stipend rates can change only in the first academic month.'):m.includes('consent')?t('학생의 숙박 동의를 확인해 주세요.','Confirm the student’s consent for shared accommodation.'):m.includes('gender')||m.includes('room')?t('공동 숙박 조건을 확인해 주세요. 다른 성별 또는 미지정이면 방 2개가 필요합니다.','Check accommodation: different or unspecified genders require two rooms.'):m.includes('limit')?t('책임연구 3개·전체 참여 5개 한도를 확인하세요.','Check the grant participation limit.'):m.includes('fund')||m.includes('Budget')?t('연구비 잔액이 부족합니다. 계획을 조정해 주세요.','Funding is insufficient. Adjust the plan.'):m.includes('workload')||m.includes('eight')?t(`교수 업무칸의 합계를 ${facultyCapacity(s).credits}로 맞춰 주세요.`,`Faculty workload units must add up to ${facultyCapacity(s).credits}.`):m;}
async function advance(){if(busy)return;busy=true;updateCosts();try{const next=await runEngine('month',{state:s,plan:s.plan,options:{feedback:s.feedback,allocation:s.allocation,budget:s.lab.budget,policies:s.policies,facultyAction:s.facultyAction,grantApplication,proposal:proposeSchedule(s),travelConsent}});if(!fast&&!matchMedia('(prefers-reduced-motion:reduce)').matches){const overlay=$('#transition');let skip=false;overlay.hidden=false;const skipHandler=event=>{if(event.target.closest('[data-skip-weeks]'))skip=true;};overlay.addEventListener('click',skipHandler);try{for(let i=0;i<4&&!skip;i++){overlay.innerHTML=weeklyScene(next,next.lastReport.results[i],i)+'<button class="week-skip" data-skip-weeks>이번 달 연출 건너뛰기 →</button>';await new Promise(r=>setTimeout(r,1200));}}finally{overlay.removeEventListener('click',skipHandler);overlay.hidden=true;}}s=next;void recordAnalytics(s);if(!s.pending&&!s.ending)s.allocation=allocateCredits(s.allocation,facultyCapacity(s).credits);if(!s.pending&&!s.ending){s.plan=proposeSchedule(s);s.allocation=allocateCredits(s.allocation,facultyCapacity(s).credits);s.feedback='listen';s.facultyAction='routine';}travelConsent=false;await archive();save();render();if(s.pending)$('#decision')?.scrollIntoView({behavior:fast?'auto':'smooth',block:'center'});else if(s.ending)openLetter(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));else toast(t('또 한 달의 기록이 쌓였습니다.','Another month in the notebook.'));}catch(error){toast(errorMessage(error));}finally{busy=false;$('#transition').hidden=true;updateCosts();}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ui]');if(!b||b.disabled||busy)return;const ui=b.dataset.ui;if(ui==='export-analysis'){await exportAnalytics();return;}if(ui==='read-entry'){openLetter(gallery.find(x=>x.id===b.dataset.entry));return;}if(ui==='record-cv'){await showCV(gallery.find(x=>x.id===b.dataset.entry));return;}if(ui==='current-statistics'){modal(renderStatistics(endingStatistics(s))+credits());return;}if(ui==='view-statistics'){const record=letter?.statistics||(letter?null:endingStatistics(s));modal((record?renderStatistics(record):'<p>이전 버전의 기록에는 파라미터가 보관되어 있지 않습니다.</p>')+credits());return;}if(ui==='advance'){await advance();return;}if(ui==='language'){lang=lang==='ko'?'en':'ko';s.locale=lang;s.plan=proposeSchedule(s);if(!isBreak()&&s.facultyAction.startsWith('abroad'))s.facultyAction='routine';save();render();return;}if(ui==='view-cv'){await showCV(letter);return;}if(ui==='view-current-cv'){await showCV(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));return;}if(ui==='download-cv'){downloadCV();return;}if(ui==='print-cv'){window.print();return;}if(ui==='guide'){guide();return;}if(ui==='settings'){settings();return;}if(ui==='close'){$('#modal').close();return;}if(ui==='print'){window.print();return;}if(ui==='decide'){busy=true;try{const choice=s.pending.kind==='event'?Number(b.dataset.choice):b.dataset.choice;s=await runEngine('decision',{state:s,choice});void recordAnalytics(s);if(!s.pending&&!s.ending){s.plan=proposeSchedule(s);s.allocation=allocateCredits(s.allocation,facultyCapacity(s).credits);s.feedback='listen';s.facultyAction='routine';}await archive();save();render();if(s.ending)openLetter(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));}catch(error){toast(errorMessage(error));}finally{busy=false;updateCosts();}return;}if(ui==='read-current'){openLetter(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));return;}if(ui==='read'){openLetter(gallery.find(x=>x.ending===b.dataset.ending));return;}if(ui==='next-page'){page++;showLetter();return;}if(ui==='prev-page'){page--;showLetter();return;}if(ui==='finish-letter'){$('#modal').close();location.hash='letters';return;}if(ui==='new'){newGame();return;}if(ui==='confirm-new'){s=freshState();letter=null;page=0;save();$('#modal').close();location.hash='lab';render();window.scrollTo(0,0);return;}if(ui==='export'){exportSave();return;}if(ui==='import'){$('#import-file').click();return;}if(ui==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;$('#modal').close();}});
document.addEventListener('submit',e=>{if(e.target.id!=='start-form')return;e.preventDefault();const data=new FormData(e.target);const original=s,seed=original.creationSeed||Date.now();s=createState('',seed,{professorGender:data.get('professorGender'),professorProfile:{gender:data.get('professorGender'),age:Number(data.get('professorAge')),fieldId:data.get('fieldId'),labMode:data.get('labMode'),institution:data.get('institution')},locale:lang});s.creationSeed=seed>>>0;s.name=generateKoreanName(seed,s.gender);s.professorName=String(data.get('professorName')).trim().slice(0,40)||'지도교수';s.started=true;void recordAnalytics(s);save();render();toast(t('첫 면담이 시작되었습니다.','Your first meeting begins.'));});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.allocation){s.allocation[el.dataset.allocation]=Number(el.value);updateCosts();}if(el.dataset.budget){s.lab.budget[el.dataset.budget]=Number(el.value);updateCosts();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='analytics-consent'){await setAnalyticsConsent(el.checked);if(s.started)void recordAnalytics(s);return;}if(el.name==='fieldId'||el.name==='institution'){updateProfileSetup();return;}if(el.dataset.policy){s.policies??={...DEFAULT_POLICIES};s.policies[el.dataset.policy]=el.value;save();return;}if(el.dataset.week!==undefined){s.plan[Number(el.dataset.week)]=el.value;const p=el.closest('.week-plan');p.querySelector('.week-desc').textContent=activityDescription(el.value);save();return;}if(el.name==='feedback'){s.feedback=el.value;$('.feedback-options').querySelectorAll('label').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));save();return;}if(el.dataset.allocation||el.dataset.budget){updateCosts();save();return;}if(el.id==='grant-role'||el.id==='grant-years'){grantApplication[el.id==='grant-role'?'role':'years']=el.id==='grant-role'?el.value:Number(el.value);updateCosts();return;}if(el.id==='faculty-action'){s.facultyAction=el.value;updateCosts();save();return;}if(el.id==='travel-consent'){travelConsent=el.checked;return;}if(el.id==='fast-mode'){fast=el.checked;save();return;}if(el.id!=='import-file')return;const file=el.files[0];if(!file)return;if(file.size>1500000){toast(t('저장 파일이 너무 큽니다.','Save file is too large.'));return;}try{const data=JSON.parse(await file.text());if(data.format!=='professor-maker'||![3,VERSION].includes(data.version)||!validateSave(data.state=migrateSave(data.state))||!Array.isArray(data.gallery)||data.gallery.length>40||!data.gallery.every(validLetter))throw new Error('Invalid save');modal(`<h2>${t('저장 파일을 불러올까요?','Import this save?')}</h2><p>${esc(data.state.name)} · ${calendar(data.state.month)}<br>${t('현재 게임을 바꾸고 기존 메일은 함께 보관합니다.','Replace the current run and keep existing discovered letters.')}</p><button class="primary" id="confirm-import">${t('불러오기','Import')}</button>`);$('#confirm-import').addEventListener('click',()=>{s=data.state;s.locale='ko';if(!s.pending&&!s.ending)s.plan=proposeSchedule(s);const seen=new Set(gallery.map(x=>x.id));gallery=[...gallery,...data.gallery.filter(x=>!seen.has(x.id))].slice(0,40);archive();save();$('#modal').close();location.hash='lab';render();toast(t('저장 파일을 불러왔습니다.','Save imported.'));});}catch{toast(t('유효한 월간 버전 저장 파일이 아닙니다.','Not a valid monthly-version save.'));}});
matchMedia('(min-width:900px)').addEventListener('change',e=>{const d=$('.student-details');if(d)d.open=e.matches;});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
$('#modal').addEventListener('click',e=>{if(e.target!==$('#modal'))return;const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();});
$('#modal').addEventListener('keydown',e=>{if(!letter||!$('.letter-reader'))return;if(e.key==='ArrowRight'&&page<endingPages().length-1){page++;showLetter();}if(e.key==='ArrowLeft'&&page>0){page--;showLetter();}});
render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
